insert into public.districts (id, city_slug, slug, sort_order, price_level, geometry)
values ('00000000-0000-0000-0000-000000000611', 'da-nang', 'fpt-city', 8, 'average',
	st_multi(st_geomfromgeojson('{"type":"Polygon","coordinates":[[[108.243,16.042],[108.257,16.042],[108.257,16.021],[108.243,16.021],[108.243,16.042]]]}')))
on conflict (city_slug, slug) do update
set geometry = excluded.geometry, sort_order = excluded.sort_order, price_level = excluded.price_level;

insert into public.district_localizations (district_id, language, name, area, rent_range, distance_to_beach, summary, best_for)
values
	('00000000-0000-0000-0000-000000000611', 'ru', 'FPT City', 'юго-восток, квартал у FPT University', '6-12 млн ₫', '5 мин пешком до моря',
	 'Современный квартал вокруг FPT University: новые дома и квартиры, студенты и айтишники, недорогие комнаты и апарты. Спокойно, зелено, своя инфраструктура - хороший компромисс между ценой и новизной.', '{budget,quiet,expat}'),
	('00000000-0000-0000-0000-000000000611', 'en', 'FPT City', 'south-east, the FPT University quarter', '6-12M VND', '5 min walk to the beach',
	 'A modern quarter around FPT University: new buildings, students and IT crowd, affordable rooms and apartments. Calm, green, with its own infrastructure - a good price-to-newness compromise.', '{budget,quiet,expat}')
on conflict (district_id, language) do update
set name = excluded.name, area = excluded.area, rent_range = excluded.rent_range,
	distance_to_beach = excluded.distance_to_beach, summary = excluded.summary, best_for = excluded.best_for;

-- Carve the FPT quarter out of Ngu Hanh Son so the exact ward boundary and
-- the quarter polygon never overlap.
update public.districts
set geometry = st_multi(st_collectionextract(st_makevalid(
	st_difference(
		(select geometry from public.districts where city_slug = 'da-nang' and slug = 'ngu-hanh-son'),
		(select geometry from public.districts where city_slug = 'da-nang' and slug = 'fpt-city')
	)), 3))
where city_slug = 'da-nang' and slug = 'ngu-hanh-son';

-- Texts follow the shrunken shapes.
update public.district_localizations dl
set area = 'Северо-запад: Хоа Кхань, Нам О', summary = 'Промышленный север с самыми низкими ценами в городе: студия от 2,5 млн ₫, дикий рыбацкий пляж Nam О, студенты и бюджетные зимовщики. Коворкингов и англоязычной среды почти нет, ночью шумят фуры - но до центра 20 минут.'
from public.districts d
where d.id = dl.district_id and d.slug = 'lien-chieu' and dl.language = 'ru';

update public.district_localizations dl
set area = 'North-west: Hoa Khanh, Nam O', summary = 'The industrial north with the lowest prices in town: studios from 2.5M VND, the wild fishing beach Nam O, students and long-term budget stayers. Almost no coworkings or English-speaking scene, trucks rumble at night - but the center is 20 minutes away.'
from public.districts d
where d.id = dl.district_id and d.slug = 'lien-chieu' and dl.language = 'en';

update public.district_localizations dl
set summary = 'Огромная сельская половина Дананга: рисовые поля, деревенская тишина, южные приморские коммуны Хоа Фуок и Хоа Тьен. Самая дешёвая жизнь, никакой туристической инфраструктуры - жить с своим байком.'
from public.districts d
where d.id = dl.district_id and d.slug = 'hoa-vang' and dl.language = 'ru';

update public.district_localizations dl
set summary = 'The vast rural half of Da Nang: rice fields, village quiet, and the southern coastal communes of Hoa Phuoc and Hoa Tien. The cheapest life around, zero tourist infrastructure - live here with your own bike.'
from public.districts d
where d.id = dl.district_id and d.slug = 'hoa-vang' and dl.language = 'en';
